import lounge from './maps/lounge.json' with { type: 'json' };
import office from './maps/office.json' with { type: 'json' };
import home from './maps/home.json' with { type: 'json' };
import { parseMap, type OfficeMap } from './map.ts';

const BUILT_IN_DATA = [lounge, office, home];

/**
 * Maps that ship with the app, generated by `tools/build_maps.py` into `./maps/<id>.json`, the
 * default (Lounge & Café) first. They are listed and playable even with an empty store; a saved
 * copy with the same id takes precedence only while it is based on the current `rev`.
 */
export const BUILT_IN_MAPS: readonly OfficeMap[] = BUILT_IN_DATA.map((data) => {
  const map = parseMap(data);
  if (!map) throw new Error('invalid built-in map');
  return map;
});

/** The map the join screen, the editor and the transports fall back to. */
export const DEFAULT_MAP: OfficeMap = BUILT_IN_MAPS[0]!;

export function builtInMap(id: string): OfficeMap | null {
  return BUILT_IN_MAPS.find((m) => m.id === id) ?? null;
}

/** The current revision of a built-in map (bumped in the generator on layout changes); 0 = none. */
export function builtInRev(id: string): number {
  return BUILT_IN_DATA.find((d) => d.id === id)?.rev ?? 0;
}
